inputs = ['vd', 'fbybc', 'dwkvg', 'jx', 'wy']
outputs = ['yaw', 'fffcc', 'awwkyg', 'jx', 'wy']

# Analyze each changed pair
changed_pairs = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changed_pairs.append((i, inp, outp))
        print(f"Pair {i}: '{inp}' -> '{outp}'")

print("\nAnalyzing transformations:")
for idx, inp, outp in changed_pairs:
    print(f"\nFrom '{inp}' to '{outp}':")

    # Find differences
    min_len = min(len(inp), len(outp))
    diff_positions = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            diff_positions.append(j)

    # Check if it's a simple substitution or replacement
    if len(inp) == len(outp):
        # Same length - check character by character
        for j in range(len(inp)):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
    elif len(inp) > len(outp):
        # Shorter output - possible deletion
        print(f"  Deletion occurred")
    else:
        # Longer output - possible insertion
        print(f"  Insertion occurred")

